import math

n = int(input())
for i in range(n):
    x = int(input())
    y = int(input())
    print(f"({x}, {y})")
    if x == 0:
        if y > 0:
            angle = 90
            print("  x = 0 and y > 0: straight up, 90")
        else:
            angle = -90
            print("  x = 0 and y < 0: straight down, -90")
    elif y == 0 and x < 0:
        angle = 180
        print("  y = 0 and x < 0: straight left, 180")
    else:
        a = math.degrees(math.atan(y / x))
        print(f"  arctan({y}/{x}) = {a:.2f}")
        if x > 0:
            angle = a
            print(f"  x > 0, so that's the angle: {angle:.2f}")
        elif y >= 0:
            angle = a + 180
            print(f"  x < 0 and y >= 0, so add 180: {angle:.2f}")
        else:
            angle = a - 180
            print(f"  x < 0 and y < 0, so take away 180: {angle:.2f}")
    if angle < 0:
        print(f"  in [0, 360): {angle:.2f} + 360 = {angle + 360:.2f}")
    else:
        print(f"  in [0, 360): {angle:.2f}")
    print(f"  check: math.atan2 gives {math.degrees(math.atan2(y, x)):.2f}")
